50	 * Scheduling strategy with restriction that clustering groups can only contain files from same partition.
51	 */
52	@Slf4j
53	public abstract class PartitionAwareClusteringPlanStrategy<T,I,K,O> extends ClusteringPlanStrategy<T,I,K,O> implements IncrementalPartitionAwareStrategy {
54	
55	  public PartitionAwareClusteringPlanStrategy(HoodieTable table, HoodieEngineContext engineContext, HoodieWriteConfig writeConfig) {
56	    super(table, engineContext, writeConfig);
57	  }
58	
59	  /**
60	   * Create Clustering group based on files eligible for clustering in the partition.
61	   * return stream of HoodieClusteringGroup and boolean partial Scheduled indicating whether all given fileSlices in the current partition have been processed.
62	   * For example, if some file slices will not be processed due to writeConfig.getClusteringMaxNumGroups(), then return false
63	   */
64	  protected Pair<Stream<HoodieClusteringGroup>, Boolean> buildClusteringGroupsForPartition(String partitionPath, List<FileSlice> fileSlices) {
65	    HoodieWriteConfig writeConfig = getWriteConfig();
66	
67	    List<Pair<List<FileSlice>, Integer>> fileSliceGroups = new ArrayList<>();
68	    List<FileSlice> currentGroup = new ArrayList<>();
69	
70	    // Sort fileSlices before dividing, which makes dividing more compact
71	    List<FileSlice> sortedFileSlices = new ArrayList<>(fileSlices);
72	    sortedFileSlices.sort((o1, o2) -> (int)
73	        ((o2.getBaseFile().isPresent() ? o2.getBaseFile().get().getFileSize() : writeConfig.getParquetMaxFileSize())
74	            - (o1.getBaseFile().isPresent() ? o1.getBaseFile().get().getFileSize() : writeConfig.getParquetMaxFileSize())));
75	
76	    long totalSizeSoFar = 0;
77	    boolean partialScheduled = false;
78	
79	    for (FileSlice currentSlice : sortedFileSlices) {
80	      long currentSize = currentSlice.getBaseFile().isPresent() ? currentSlice.getBaseFile().get().getFileSize() : writeConfig.getParquetMaxFileSize();
81	      // check if max size is reached and create new group, if needed.
82	      if (totalSizeSoFar + currentSize > writeConfig.getClusteringMaxBytesInGroup() && !currentGroup.isEmpty()) {
83	        int numOutputGroups = getNumberOfOutputFileGroups(totalSizeSoFar, writeConfig.getClusteringTargetFileMaxBytes());
84	        log.info("Adding one clustering group " + totalSizeSoFar + " max bytes: "
85	            + writeConfig.getClusteringMaxBytesInGroup() + " num input slices: " + currentGroup.size() + " output groups: " + numOutputGroups);
86	        fileSliceGroups.add(Pair.of(currentGroup, numOutputGroups));
87	        currentGroup = new ArrayList<>();
88	        totalSizeSoFar = 0;
89	
90	        // if fileSliceGroups's size reach the max group, stop loop
91	        if (fileSliceGroups.size() >= writeConfig.getClusteringMaxNumGroups()) {
92	          log.info("Having generated the maximum number of groups : " + writeConfig.getClusteringMaxNumGroups());
93	          partialScheduled = true;
94	          break;
95	        }
96	      }
97	
98	      // Add to the current file-group
99	      currentGroup.add(currentSlice);
100	      // assume each file group size is ~= parquet.max.file.size
101	      totalSizeSoFar += currentSize;
102	    }
103	
104	    if (!currentGroup.isEmpty()) {
105	      if (currentGroup.size() > 1 || writeConfig.shouldClusteringSingleGroup()) {
106	        int numOutputGroups = getNumberOfOutputFileGroups(totalSizeSoFar, writeConfig.getClusteringTargetFileMaxBytes());
107	        log.info("Adding final clustering group " + totalSizeSoFar + " max bytes: "
108	            + writeConfig.getClusteringMaxBytesInGroup() + " num input slices: " + currentGroup.size() + " output groups: " + numOutputGroups);
109	        fileSliceGroups.add(Pair.of(currentGroup, numOutputGroups));
110	      }
111	    }
112	
113	    return Pair.of(fileSliceGroups.stream().map(fileSliceGroup ->
114	        HoodieClusteringGroup.newBuilder()
115	            .setSlices(getFileSliceInfo(fileSliceGroup.getLeft()))
116	            .setNumOutputFileGroups(fileSliceGroup.getRight())
117	            .setMetrics(buildMetrics(fileSliceGroup.getLeft()))
118	            .build()), partialScheduled);
119	  }
