122	    Set<HoodieFileGroupId> fgIdsInPendingCompactionLogCompactionAndClustering =
123	        Stream.concat(fileSystemView.getPendingCompactionOperations(), fileSystemView.getPendingLogCompactionOperations())
124	            .map(instantTimeOpPair -> instantTimeOpPair.getValue().getFileGroupId())
125	            .collect(Collectors.toSet());
126	    fgIdsInPendingCompactionLogCompactionAndClustering.addAll(fileSystemView.getFileGroupsInPendingClustering().map(Pair::getKey).collect(Collectors.toSet()));
127	
128	    return hoodieTable.getSliceView().getLatestFileSlicesStateless(partition)
129	        // file ids already in clustering are not eligible
130	        .filter(slice -> !fgIdsInPendingCompactionLogCompactionAndClustering.contains(slice.getFileGroupId()));
131	  }
